def R(id, fam, src, sec, text, quote, applies, ct, det, sev, link=None, note=None):
    return dict(id=id, family=fam, source=dict(key=src, section=sec), rule_text=text, quote=quote, applies_to=applies,
                check_type=ct, detection=det, severity=sev, link=link or {}, note=note)
def D(check, logic, inputs=("text",)): return dict(check_fn=check, logic=logic, inputs=list(inputs))
def J(q, pas, fail): return dict(question=q, pass_anchor=pas, fail_anchor=fail)

